const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const action = body.action
  || (body.case_number || body.last_name ? 'case_lookup'
    : (body.query ? 'kb_search' : 'list_courts'));

const api = ($env.COURT_KB_API_URL || 'http://127.0.0.1:8080').replace(/\/$/, '');
const apiKey = $env.COURT_KB_API_KEY || '';

let method = 'POST';
let url = api;
let payload = {};

if (action === 'case_lookup') {
  if (!body.court_slug) {
    return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать court_slug (например, sovetsky-vrn). Сначала вызовите action=list_courts.' } }];
  }
  if (!body.case_number && !body.last_name) {
    return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать case_number или last_name.' } }];
  }
  url = api + '/case-lookup';
  payload = {
    court_slug: body.court_slug,
    case_number: body.case_number || null,
    last_name: body.last_name || null,
    production_type: body.production_type || 'civil_first_instance',
  };
} else if (action === 'kb_search') {
  if (!body.query) {
    return [{ json: { skipHttp: true, status: 'error', result: 'Нужно указать query.' } }];
  }
  url = api + '/kb/search';
  payload = {
    query: body.query,
    court_slug: body.court_slug || null,
    top_k: body.top_k || 3,
  };
} else if (action === 'list_courts') {
  url = api + '/courts';
  payload = {};
} else {
  return [{ json: { skipHttp: true, status: 'error', result: 'Неизвестное action: ' + action + '. Допустимо: case_lookup, kb_search, list_courts.' } }];
}

return [{ json: { skipHttp: false, method, url, payload, apiKey, action } }];
